<script setup lang="ts">
const props=defineProps<{data:any}>()
const {t,locale}=useI18n(),staff=useStaffStore()
const percent=(n:number)=>props.data.total?Math.round(100*n/props.data.total)+'%':'—'
const number=(n:number)=>n.toLocaleString(locale.value)
const canView=computed(()=>staff.hasPermission('goods_read'))
</script>
<template><WCard class="spec-coverage" :title="t('inbound-spec.title')"><template #actions><NuxtLink v-if="canView" :to="{path:'/goods',query:{spec_missing:'weight,dimensions'}}">{{t('inbound-spec.collect')}} →</NuxtLink></template><p class="help">{{t('inbound-spec.help')}}</p><div class="headline"><strong>{{percent(data.complete)}}</strong><span>{{t('inbound-spec.complete',{complete:number(data.complete),total:number(data.total)})}}</span></div><div class="meters"><div v-for="key in ['weight','dimensions']" :key="key" class="meter"><span>{{t('inbound-spec.'+key)}}</span><span role="img" :aria-label="t('inbound-spec.'+key)+': '+percent(data[key])" class="track"><i :style="{width:(data.total?100*data[key]/data.total:0)+'%'}"/></span><span class="count"><b>{{percent(data[key])}}</b> · {{number(data[key])}} / {{number(data.total)}}</span></div></div><div v-if="data.missing_total" class="missing"><p>{{t('inbound-spec.missing',{count:number(data.missing_total)})}}</p><div v-for="row in data.missing" :key="row.id" class="missing-row"><NuxtLink v-if="canView" class="w-spec-name name" :to="'/goods/detail/'+row.id" :title="row.name">{{row.name}}</NuxtLink><span v-else class="w-spec-name name" :title="row.name">{{row.name}}</span><span class="badge">{{row.missing.map((key:string)=>t('inbound-spec.'+key)).join(' · ')}}</span><small>{{row.code}} · {{t('inbound-spec.received',{count:number(row.quantity)})}}</small></div><small v-if="data.missing_total>data.missing.length">{{t('inbound-spec.limit',{count:data.missing.length})}}</small></div><p v-else class="help">{{t(data.total?'inbound-spec.all-complete':'inbound-spec.empty')}}</p></WCard></template>
